/* runtime.h: what the literal C translation of XnGine (src/xngine_c/xn_*.c, generated by
   tools/xn_c.py) runs on.

   The C is the asm, one instruction at a time, on a register file R kept in memory. Memory is
   the game's own: flat 32-bit pointers, with an XnGine or game address va at XN(va) (the
   emulator loads the LE objects at 0x01000000 + their preferred address). Stack operations
   work on R.esp in that memory, so pushes, calls and returns write the same bytes as the asm;
   the C's own frames live on a separate stack.

   Arithmetic flags are lazy: an instruction whose flags something may read stores what it did
   (F: operation and size, operands, result) and the flags are worked out when read. While F.op
   is XF_NONE they are in R.eflags. Compare-and-branch pairs become C comparisons.

   Control leaves C only through the asm helpers in xn_rt.asm: a C function is entered from asm
   through xn_thunk (registers to R, then the call), and returns, or jumps anywhere, by setting
   xn_ret and returning to it (R to registers, then jmp xn_ret); xn_call runs asm (or another
   translated function, through its asm entry) as a call. C runs with interrupts off; R.eflags
   keeps the program's IF. Watcom C32 10.0a has no 64-bit integers, so 32x32 multiplies and
   64/32 divides are inline `mul`/`div` instructions. */
#ifndef XN_RUNTIME_H
#define XN_RUNTIME_H

typedef unsigned char u8;
typedef unsigned short u16;
typedef unsigned int u32;
typedef signed char s8;
typedef short s16;
typedef int s32;

struct xn_regs {
    u32 eax, ecx, edx, ebx, esp, ebp, esi, edi;     /* in x86 register-number order */
    u32 eflags;
    u32 es, cs, ss, ds, fs, gs;
};
extern struct xn_regs R;

/* lazy arithmetic flags: op = kind << 2 | size (0: 8 bits, 1: 16, 2: 32) */
struct xn_lazy {
    u32 op, a, b, r;    /* operands and result (see runtime.c for each kind) */
    u32 x;              /* ADC/SBB: the carry in; INC/DEC: CF kept from before */
};
extern struct xn_lazy F;

#define XF_NONE   0     /* the flags are in R.eflags */
#define XF_ADD    (1 << 2)
#define XF_ADC    (2 << 2)
#define XF_SUB    (3 << 2)
#define XF_SBB    (4 << 2)
#define XF_LOGIC  (5 << 2)
#define XF_INC    (6 << 2)
#define XF_DEC    (7 << 2)
#define XF_SHL    (8 << 2)      /* a: the value shifted by count - 1 */
#define XF_SAR    (9 << 2)      /* shr and sar; a: the value shifted by count - 1 */
#define XF_MUL    (10 << 2)     /* r: low half; b: nonzero when the result overflowed */

#define LF(o, A, B, Rr) (F.op = (o), F.a = (A), F.b = (B), F.r = (Rr))

u32 xn_cf(void);
u32 xn_cond(u32 cc);            /* x86 condition code 0-15 (jo .. jg) */
u32 xn_eflags(void);            /* EFLAGS with the arithmetic flags made concrete */
extern const u8 xn_parity[256]; /* PF for a low byte */

/* memory */
#define XN_LOAD 0x01000000u
#define XN(va) ((u32)(va) + XN_LOAD)
#define M8(a)  (*(u8 *)(a))
#define M16(a) (*(u16 *)(a))
#define M32(a) (*(u32 *)(a))

/* sub-registers */
#define AL (((u8 *)&R.eax)[0])
#define AH (((u8 *)&R.eax)[1])
#define CL (((u8 *)&R.ecx)[0])
#define CH (((u8 *)&R.ecx)[1])
#define DL (((u8 *)&R.edx)[0])
#define DH (((u8 *)&R.edx)[1])
#define BL (((u8 *)&R.ebx)[0])
#define BH (((u8 *)&R.ebx)[1])
#define AX (*(u16 *)&R.eax)
#define CX (*(u16 *)&R.ecx)
#define DX (*(u16 *)&R.edx)
#define BX (*(u16 *)&R.ebx)
#define SP (*(u16 *)&R.esp)
#define BP (*(u16 *)&R.ebp)
#define SI (*(u16 *)&R.esi)
#define DI (*(u16 *)&R.edi)

/* the asm stack */
#define PUSH32(v) (R.esp -= 4, M32(R.esp) = (v))
#define PUSH16(v) (R.esp -= 2, M16(R.esp) = (v))

/* leaving C: return to the caller, or continue in asm at an address */
extern u32 xn_ret;
extern u32 xn_retcs;
extern u32 xn_far;
#define XN_DONE         /* what a function returns when control leaves it (-1 in parts) */
#define RET(n) do { xn_ret = M32(R.esp); R.esp += 4 + (n); return XN_DONE; } while (0)
#define GOTO_ASM(a) do { xn_ret = (a); return XN_DONE; } while (0)

/* asm helpers (xn_rt.asm) */
void xn_call(u32 target);       /* call: [R.esp] holds the return address the callee sees */
#pragma aux xn_call "*" parm [eax] modify [eax];
void xn_int(u32 vector);        /* int n with R */
#pragma aux xn_int "*" parm [eax] modify [eax];
void xn_divfault(void);         /* a divide error, taken by the program's own handler */
#pragma aux xn_divfault "*" modify [eax];

/* port I/O */
u8 xn_in8(u32 port);
#pragma aux xn_in8 = "in al, dx" parm [edx] value [al];
u16 xn_in16(u32 port);
#pragma aux xn_in16 = "in ax, dx" parm [edx] value [ax];
u32 xn_in32(u32 port);
#pragma aux xn_in32 = "in eax, dx" parm [edx] value [eax];
void xn_out8(u32 port, u8 v);
#pragma aux xn_out8 = "out dx, al" parm [edx] [al];
void xn_out16(u32 port, u16 v);
#pragma aux xn_out16 = "out dx, ax" parm [edx] [ax];
void xn_out32(u32 port, u32 v);
#pragma aux xn_out32 = "out dx, eax" parm [edx] [eax];

/* 32 x 32 -> 64 multiplies: the low half, the high half through hi */
u32 xn_mulu(u32 a, u32 b, u32 *hi);
#pragma aux xn_mulu = "mul edx" "mov [ebx], edx" parm [eax] [edx] [ebx] value [eax] modify [edx];
u32 xn_muls(u32 a, u32 b, u32 *hi);
#pragma aux xn_muls = "imul edx" "mov [ebx], edx" parm [eax] [edx] [ebx] value [eax] modify [edx];

/* divides: as div/idiv r/m of size 1, 2 or 4 bytes, on R; a divide error goes to the program's
   handler as the CPU's would (va: the instruction, for the fault frame) */
extern u32 xn_faulted;           /* set when a divide faulted */
void xn_div(u32 d, u32 size, u32 va);
void xn_idiv(u32 d, u32 size, u32 va);

/* one-operand multiplies on R (mul/imul r/m), setting the lazy flags */
void xn_mul1(u32 v, u32 size);
void xn_imul1(u32 v, u32 size);
/* imul r, r/m(, imm): the truncated product, with the lazy flags */
u32 xn_imul2(u32 a, u32 b, u32 size);

/* string instructions on R (rep: ECX times; scas/cmps set the lazy flags) */
void xn_movs(u32 size, u32 rep);
void xn_stos(u32 size, u32 rep);
void xn_lods(u32 size, u32 rep);
void xn_scas(u32 size, u32 rep);    /* rep: 0 none, 1 repe, 2 repne */
void xn_cmps(u32 size, u32 rep);
void xn_ins(u32 size, u32 rep);
void xn_outs(u32 size, u32 rep);

/* flag instructions that change some flags and keep the rest */
void xn_setcf(u32 cf);
void xn_rotate(u32 kind, u32 size, void *dst, u32 count);   /* 0 rol, 1 ror, 2 rcl, 3 rcr */
u32 xn_bsf(u32 src, u32 old);
u32 xn_bsr(u32 src, u32 old);
void xn_popf(u32 v);

#endif
